"use client";
import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import { Input } from "@/components/ui/input";
export const paginationVariants = cva("v-pager");
export type PaginationProps = React.ComponentProps<"nav"> & {
  page?: number;
  defaultPage?: number;
  totalPages?: number;
  onPageChange?: (page: number) => void;
  /** Direct pages, a reading position, or exact entry for a large collection. */
  appearance?: "pages" | "chapter" | "jump";
};
export function Pagination({
  ref,
  className,
  page,
  defaultPage = 1,
  totalPages,
  onPageChange,
  children,
  appearance = "pages",
  ...props
}: PaginationProps) {
  const [local, setLocal] = React.useState(defaultPage);
  const total = Math.max(
    1,
    Math.floor(Number.isFinite(totalPages) ? totalPages! : 1),
  );
  const current = Math.min(
    total,
    Math.max(
      1,
      Math.floor(Number.isFinite(page ?? local) ? (page ?? local) : 1),
    ),
  );
  // A fixed seven-slot window does not move the next/previous hit targets.
  const pages: (number | "start-gap" | "end-gap")[] =
    total <= 7
      ? Array.from({ length: total }, (_, index) => index + 1)
      : current <= 4
        ? [1, 2, 3, 4, 5, "end-gap", total]
        : current >= total - 3
          ? [1, "start-gap", total - 4, total - 3, total - 2, total - 1, total]
          : [
              1,
              "start-gap",
              current - 1,
              current,
              current + 1,
              "end-gap",
              total,
            ];
  const change = (next: number) => {
    const clamped = Math.max(1, Math.min(total, next));
    if (page === undefined) setLocal(clamped);
    if (clamped !== current) onPageChange?.(clamped);
  };
  return (
    <nav
      ref={ref}
      data-slot="pagination"
      data-part="root"
      data-pager=""
      data-pages={total}
      data-page={current}
      data-appearance={appearance}
      data-composed={children == null || undefined}
      aria-label="Pagination"
      className={cn(paginationVariants(), className)}
      {...props}
    >
      {children ?? (
        <>
          <PaginationPrevious
            disabled={current === 1}
            onClick={() => change(current - 1)}
          />
          {appearance === "pages" ? (
            <div className="v-pager__pages">
              {pages.map((n) =>
                typeof n === "number" ? (
                  <PaginationLink
                    key={n}
                    isActive={n === current}
                    aria-label={`Page ${n}`}
                    onClick={() => change(n)}
                  >
                    {n}
                  </PaginationLink>
                ) : (
                  <PaginationEllipsis key={n} />
                ),
              )}
            </div>
          ) : appearance === "chapter" ? (
            <div className="v-pager__chapter" aria-hidden="true">
              <span>Chapter</span>
              <strong>
                {String(current).padStart(2, "0")}{" "}
                <small>/ {String(total).padStart(2, "0")}</small>
              </strong>
              <span className="v-pager__track">
                <span style={{ transform: `scaleX(${current / total})` }} />
              </span>
            </div>
          ) : (
            <PaginationJump current={current} total={total} onChange={change} />
          )}
          <PaginationNext
            disabled={current === total}
            onClick={() => change(current + 1)}
          />
          <span className="v-pager__info" aria-live="polite">
            Page {current} of {total}
          </span>
        </>
      )}
    </nav>
  );
}
function PaginationJump({
  current,
  total,
  onChange,
}: {
  current: number;
  total: number;
  onChange: (page: number) => void;
}) {
  const input = React.useRef<HTMLInputElement>(null);
  const id = React.useId();
  const [error, setError] = React.useState("");
  React.useEffect(() => {
    if (input.current) input.current.value = String(current);
  }, [current]);
  const submit = () => {
    const value = input.current?.valueAsNumber;
    if (!Number.isInteger(value) || value! < 1 || value! > total) {
      setError(`Choose a whole page from 1 to ${total}.`);
      input.current?.focus();
      return;
    }
    setError("");
    onChange(value!);
  };
  return (
    <div className="v-pager__jump">
      <label htmlFor={id}>Go to page</label>
      <div className="v-pager__entry">
        <Input
          ref={input}
          id={id}
          type="number"
          min={1}
          max={total}
          step={1}
          defaultValue={current}
          aria-invalid={!!error}
          aria-describedby={`${id}-hint`}
          onChange={() => setError("")}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault();
              submit();
            }
          }}
        />
        <span>of {total}</span>
        <Button variant="secondary" onClick={submit}>
          Go
        </Button>
      </div>
      <span id={`${id}-hint`} className="v-pager__hint" role="status">
        {error || "Enter an exact page number."}
      </span>
    </div>
  );
}
export type PaginationContentProps = React.ComponentProps<"ul">;
export function PaginationContent({
  className,
  ...props
}: PaginationContentProps) {
  return (
    <ul
      data-slot="pagination-content"
      className={cn("contents list-none", className)}
      {...props}
    />
  );
}
export type PaginationItemProps = React.ComponentProps<"li">;
export function PaginationItem({ className, ...props }: PaginationItemProps) {
  return (
    <li
      data-slot="pagination-item"
      className={cn("contents", className)}
      {...props}
    />
  );
}
export type PaginationLinkProps = React.ComponentProps<typeof Button> & {
  isActive?: boolean;
};
export function PaginationLink({
  className,
  isActive,
  variant,
  style,
  ...props
}: PaginationLinkProps) {
  return (
    <Button
      type="button"
      data-slot="pagination-link"
      data-stable-hit=""
      data-part="item"
      aria-current={isActive ? "page" : undefined}
      variant={variant ?? (isActive ? "accent" : "outline")}
      className={cn("v-pager__link", className)}
      style={{
        minWidth: 44,
        minHeight: 44,
        paddingInline: 10,
        transform: "none",
        ...style,
      }}
      {...props}
    />
  );
}
export type PaginationPreviousProps = PaginationLinkProps;
export function PaginationPrevious({
  children,
  ...props
}: PaginationPreviousProps) {
  return (
    <PaginationLink
      aria-label="Previous"
      data-pager-direction="previous"
      {...props}
    >
      {children ?? <Icon name="arrow-left" size="sm" aria-hidden="true" />}
    </PaginationLink>
  );
}
export type PaginationNextProps = PaginationLinkProps;
export function PaginationNext({ children, ...props }: PaginationNextProps) {
  return (
    <PaginationLink aria-label="Next" data-pager-direction="next" {...props}>
      {children ?? <Icon name="arrow-right" size="sm" aria-hidden="true" />}
    </PaginationLink>
  );
}
export type PaginationEllipsisProps = React.ComponentProps<"span">;
export function PaginationEllipsis({
  className,
  ...props
}: PaginationEllipsisProps) {
  return (
    <span
      data-slot="pagination-ellipsis"
      aria-hidden="true"
      className={cn(
        "v-ellipsis px-[4px] text-[color:var(--muted-foreground)]",
        className,
      )}
      {...props}
    >
      …
    </span>
  );
}

@layer cojeev-states {
[data-slot="pagination"] {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: var(--v-text);
}
[data-slot="pagination"][data-composed] {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px;
  column-gap: 12px;
  row-gap: 12px;
  max-width: 560px;
  width: 100%;
  box-sizing: border-box;
  padding: 12px;
}
.v-pager__pages {
  display: flex;
  justify-content: center;
  gap: 4px;
  min-width: 0;
}
.v-pager__pages [data-slot="pagination-ellipsis"] {
  display: grid;
  place-items: center;
  min-width: 44px;
  height: 44px;
  padding: 0;
}
[data-slot="pagination"] [data-slot="pagination-link"] {
  font-variant-numeric: tabular-nums;
}
.v-pager__info {
  grid-column: 1/-1;
  text-align: center;
  font-size: var(--fs-meta);
  color: var(--v-text-2);
  font-variant-numeric: tabular-nums;
}
.v-pager__chapter {
  display: grid;
  justify-items: center;
  gap: 6px;
  padding: 12px 16px;
  background: var(--v-canvas);
  border: 1px solid var(--v-edge);
  border-radius: 16px;
}
.v-pager__chapter > span:first-child {
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--v-text-2);
}
.v-pager__chapter strong {
  font-size: 28px;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}
.v-pager__chapter small {
  font-size: 14px;
  font-weight: 400;
  color: var(--v-text-2);
}
.v-pager__track {
  display: block;
  height: 3px;
  width: 100%;
  overflow: hidden;
  border-radius: 4px;
  background: var(--v-edge);
}
.v-pager__track > span {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--v-accent-ink);
  transform-origin: left;
}
.v-pager__jump {
  display: grid;
  gap: 8px;
  min-width: 0;
}
.v-pager__jump label {
  font-size: var(--fs-meta);
  font-weight: 600;
}
.v-pager__entry {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.v-pager__entry [data-slot="input"] {
  width: 80px;
  min-width: 0;
  min-height: 44px;
  flex: 1;
}
.v-pager__entry [data-slot="button"] {
  min-height: 44px;
}
.v-pager__entry > span {
  white-space: nowrap;
  font-size: var(--fs-meta);
  color: var(--v-text-2);
}
.v-pager__hint {
  font-size: 12px;
  min-height: 18px;
  color: var(--v-text-2);
}
.v-pager__example {
  display: grid;
  gap: 24px;
  min-width: 0;
}
.v-pager__specimen {
  background: var(--v-canvas);
  border: 1px solid var(--v-edge);
  border-radius: 20px;
  padding: 24px;
  display: grid;
  gap: 12px;
}
.v-pager__specimen > small {
  color: var(--v-accent-ink);
  letter-spacing: 0.12em;
  font-size: 11px;
  text-transform: uppercase;
}
.v-pager__specimen h3 {
  font-size: var(--fs-title-sm, 24px);
  margin: 0;
}
.v-pager__specimen p {
  color: var(--v-text-2);
  margin: 0;
}
@media (max-width: 640px) {
  .v-pager__pages [data-slot="pagination-ellipsis"] {
    min-width: 16px;
  }
  [data-slot="pagination"][data-composed][data-appearance="pages"]
    .v-pager__pages {
    grid-row: 1;
    grid-column: 1/-1;
    gap: 2px;
    flex-wrap: wrap;
  }
  [data-slot="pagination"][data-appearance="pages"]
    [data-pager-direction="previous"] {
    grid-row: 2;
    grid-column: 1;
  }
  [data-slot="pagination"][data-appearance="pages"]
    [data-pager-direction="next"] {
    grid-row: 2;
    grid-column: 3;
  }
  [data-slot="pagination"][data-appearance="pages"] .v-pager__info {
    grid-row: 2;
    grid-column: 2;
  }
  [data-slot="pagination"][data-appearance="jump"] {
    column-gap: 8px;
  }
  .v-pager__entry {
    gap: 6px;
    flex-wrap: wrap;
  }
}
[dir="rtl"] .v-pager__track > span {
  transform-origin: right;
}

}
